<?php

declare(strict_types=1);

namespace Nowo\SeedKitBundle\Domain\Model;

use Nowo\SeedKitBundle\Domain\Exception\InvalidValueException;
use Stringable;

use function preg_match;

/**
 * A run id: a canonical lower-case UUID (v7 when generated by the bundle).
 */
final readonly class RunId implements Stringable
{
    /**
     * @throws InvalidValueException
     */
    public function __construct(public string $value)
    {
        if (preg_match('/\A[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\z/D', $value) !== 1) {
            throw new InvalidValueException('Invalid run id.');
        }
    }

    /**
     * The id.
     */
    public function __toString(): string
    {
        return $this->value;
    }
}
